import sys
from itertools import permutations

MOD = 1000000007

def main():
    input = sys.stdin.read().split()
    n = int(input[0])
    a = list(map(int, input[1:n+1]))
    k = int(input[n+1])
    bad_luck = set(map(int, input[n+2:n+2+k]))

    def is_good_route(route):
        prefix_sum = 0
        for step in route:
            prefix_sum += step
            if prefix_sum in bad_luck:
                return False
        return True

    good_routes_count = 0
    for route in permutations(a):
        if is_good_route(route):
            good_routes_count = (good_routes_count + 1) % MOD

    print(good_routes_count)

if __name__ == "__main__":
    main()
